# Flask-style: set and read a cookie
from flask import Flask, make_response, request
app = Flask(__name__)

@app.route('/login')
def login():
    resp = make_response('set')
    resp.set_cookie('user', 'cos', max_age=3600, httponly=True, samesite='Lax')
    return resp

@app.route('/whoami')
def whoami():
    return request.cookies.get('user', 'anon')

